package com.nonet.admin;
import android.content.Context;import org.json.JSONObject;import java.io.*;import java.net.HttpURLConnection;import java.net.URL;import java.nio.charset.StandardCharsets;
public final class ApiClient{private ApiClient(){}public static String base(Context c){return c.getSharedPreferences("admin",0).getString("server_url","").trim().replaceAll("/+$","");}public static JSONObject request(Context c,String method,String path,JSONObject data,boolean auth)throws Exception{String base=base(c);if(base.isEmpty()||!base.startsWith("https://"))throw new IOException("اضبط رابط HTTPS للخادم أولاً.");HttpURLConnection x=(HttpURLConnection)new URL(base+path).openConnection();x.setRequestMethod(method);x.setConnectTimeout(10000);x.setReadTimeout(15000);x.setRequestProperty("Accept","application/json");if(auth){String token=c.getSharedPreferences("admin",0).getString("token","");if(token.isEmpty())throw new IOException("سجّل الدخول أولاً.");x.setRequestProperty("Authorization","Bearer "+token);}if(data!=null){x.setDoOutput(true);x.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream o=x.getOutputStream()){o.write(data.toString().getBytes(StandardCharsets.UTF_8));}}int code=x.getResponseCode();InputStream in=code>=200&&code<400?x.getInputStream():x.getErrorStream();StringBuilder b=new StringBuilder();if(in!=null)try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}x.disconnect();JSONObject out=b.length()>0?new JSONObject(b.toString()):new JSONObject();if(code<200||code>=300)throw new IOException(out.optString("error","HTTP "+code));return out;}}
